from jsonb_to_recordset('[{"slug": "aviation", "titre": {"ar": "مطارات الجزائر", "en": "Algeria airports", "fr": "Aéroports d''Algérie"}, "description": {"en": "Algeria''s 36 civil airports: official names, ICAO (OACI) and IATA codes, addresses, phones, websites, coordinates, and wilaya linkage. Sourced from ANAC (anac.dz) and OurAirports. JSON, CSV, GeoJSON, TypeScript."}, "readme": "Airports from the National Civil Aviation Authority (ANAC), plus Hassi R''Mel (HRM), Mécheria (MZW) and Laghouat (LOO), which ANAC''s map omits and which OurAirports supplies. IATA codes are backfilled from OurAirports by ICAO match, each one confirmed by coordinate distance rather than by code alone. Wilaya-level only (no commune linkage).", "categorie_slug": "transport", "licence_code": "donnees-publiques", "licence_details": "Factual public listing (ANAC); IATA codes and three supplementary airports from OurAirports (public domain)", "url_source": "https://www.npmjs.com/package/@geoalgeria/aviation", "mots_cles": ["aeroport", "aeroports", "airport", "airports", "algeria", "anac", "aviation", "icao", "oaci"], "wilayas": [], "frequence_maj": "hebdomadaire", "infos_source": {"bbox": [-8.165434, 19.563939, 9.63789, 36.824416], "paquet": "@geoalgeria/aviation", "couverture_pct": null, "taux_geocodage": 100, "note_couverture": "Airports from the National Civil Aviation Authority (ANAC), plus Hassi R''Mel (HRM), Mécheria (MZW) and Laghouat (LOO), which ANAC''s map omits and which OurAirports supplies. IATA codes are backfilled from OurAirports by ICAO match, each one confirmed by coordinate distance rather than by code alone. Wilaya-level only (no commune linkage).", "nb_enregistrements": 36, "nb_wilayas_couvertes": 33, "mis_a_jour_par_la_source": "2026-09-09"}}, {"slug": "divisions-administratives", "titre": {"ar": "التقسيم الإداري للجزائر (الولايات، الدوائر، البلديات)", "en": "Algeria administrative divisions (wilayas, dairas, communes)", "fr": "Divisions administratives de l''Algérie (wilayas, daïras, communes)"}, "description": {"en": "69 wilayas, 551 dairas, 1541 communes of Algeria: bilingual names, postal codes, coordinates, plus 3908 post offices & 2026 ATMs. JSON, CSV, GeoJSON, SQL, TypeScript."}, "readme": "# Divisions administratives de l''Algérie (wilayas, daïras, communes)\n\n69 wilayas, 551 dairas, 1541 communes of Algeria: bilingual names, postal codes, coordinates, plus 3908 post offices & 2026 ATMs. JSON, CSV, GeoJSON, SQL, TypeScript.\n\n**Source :** [GeoAlgeria](https://geoalgeria.com) par Yasser''s studio, paquet [geoalgeria](https://www.npmjs.com/package/geoalgeria).\n**Licence :** Mixed terms per part, stated in full in LICENSE and NOTICE. The compilation of wilayas, dairas, communes, their bilingual names, postal codes and administrative codes is MIT. The 69 wilaya boundary polygons, 323 OpenStreetMap-derived commune centre coordinates and the OpenStreetMap relation ids and Wikidata items on the commune and wilaya records are ODbL 1.0, © OpenStreetMap contributors. The mirrored postal data under data/poste: Data © Algérie Poste; redistributed for reference.\n\nSynchronisé automatiquement chaque semaine par data-dz.", "categorie_slug": "administratif", "licence_code": "ODbL-1.0", "licence_details": "Mixed terms per part, stated in full in LICENSE and NOTICE. The compilation of wilayas, dairas, communes, their bilingual names, postal codes and administrative codes is MIT. The 69 wilaya boundary polygons, 323 OpenStreetMap-derived commune centre coordinates and the OpenStreetMap relation ids and Wikidata items on the commune and wilaya records are ODbL 1.0, © OpenStreetMap contributors. The mirrored postal data under data/poste: Data © Algérie Poste; redistributed for reference.", "url_source": "https://www.npmjs.com/package/geoalgeria", "mots_cles": ["address-autocomplete", "address-form", "administrative-divisions", "algeria", "algeria-2026", "algeria-cities", "algeria-geojson", "algeria-map", "algeria-municipalities", "algeria-provinces", "algerie", "code-postal-algerie", "communes", "communes-algerie", "dairas", "ecommerce-algeria", "geodata", "postal-codes", "shipping-zones", "wilayas", "wilayas-algerie"], "wilayas": [], "frequence_maj": "hebdomadaire", "infos_source": {"bbox": null, "paquet": "geoalgeria", "couverture_pct": null, "taux_geocodage": 100, "note_couverture": null, "nb_enregistrements": 1541, "nb_wilayas_couvertes": 69, "mis_a_jour_par_la_source": "2026-10-03"}}, {"slug": "mosquees", "titre": {"ar": "مساجد الجزائر", "en": "Algeria mosques", "fr": "Mosquées d''Algérie"}, "description": {"en": "Mosques of Algeria: 20,000+ geocoded mosques compiled from Wikidata and OpenStreetMap, with Arabic & French names, denomination, commune/wilaya linkage and GPS coordinates. JSON, CSV, GeoJSON, TypeScript."}, "readme": "# Mosquées d''Algérie\n\nMosques of Algeria: 20,000+ geocoded mosques compiled from Wikidata and OpenStreetMap, with Arabic & French names, denomination, commune/wilaya linkage and GPS coordinates. JSON, CSV, GeoJSON, TypeScript.\n\n> Mosques compiled from Wikidata + OpenStreetMap, against the ~18449 counted by the Ministry of Religious Affairs (MARW). A community-maintained composite, not an official registry; the two do not count the same population, which is why the ratio exceeds 100%: OSM tags every amenity=place_of_worship/muslim, including the neighbourhood musallas and prayer rooms the MARW figure (built mosques) excludes. Read it as a comparison against the official count, not as coverage of it.\n\n**Source :** [GeoAlgeria](https://geoalgeria.com) par Yasser''s studio, paquet [@geoalgeria/mosquees](https://www.npmjs.com/package/@geoalgeria/mosquees).\n**Licence :** MIT AND ODbL-1.0\n\nSynchronisé automatiquement chaque semaine par data-dz.", "categorie_slug": "culture-tourisme", "licence_code": "ODbL-1.0", "licence_details": "MIT AND ODbL-1.0", "url_source": "https://www.npmjs.com/package/@geoalgeria/mosquees", "mots_cles": ["algeria", "masjid", "mosquees", "mosques", "openstreetmap", "places-of-worship", "religion", "wikidata"], "wilayas": [], "frequence_maj": "hebdomadaire", "infos_source": {"bbox": [-8.148174, 19.563226, 10.931214, 37.074766], "paquet": "@geoalgeria/mosquees", "couverture_pct": 112.5, "taux_geocodage": 100, "note_couverture": "Mosques compiled from Wikidata + OpenStreetMap, against the ~18449 counted by the Ministry of Religious Affairs (MARW). A community-maintained composite, not an official registry; the two do not count the same population, which is why the ratio exceeds 100%: OSM tags every amenity=place_of_worship/muslim, including the neighbourhood musallas and prayer rooms the MARW figure (built mosques) excludes. Read it as a comparison against the official count, not as coverage of it.", "nb_enregistrements": 20759, "nb_wilayas_couvertes": 69, "mis_a_jour_par_la_source": "2026-06-25"}}, {"slug": "pharmacies", "titre": {"ar": "صيدليات الجزائر", "en": "Algeria pharmacies (officines)", "fr": "Pharmacies d''Algérie"}, "description": {"en": "Algeria''s pharmacies (officines) from OpenStreetMap: geocoded, bilingual FR/AR where named, with phone/opening-hours/dispensing where tagged and wilaya/commune linkage against the geoalgeria commune set. JSON, CSV, GeoJSON, TypeScript."}, "readme": "# Pharmacies d''Algérie\n\nAlgeria''s pharmacies (officines) from OpenStreetMap: geocoded, bilingual FR/AR where named, with phone/opening-hours/dispensing where tagged and wilaya/commune linkage against the geoalgeria commune set. JSON, CSV, GeoJSON, TypeScript.\n\n> 3807 pharmacies compiled from OpenStreetMap, against an estimated ~11000 officines nationally (order-of-magnitude, no open official registry). A community-maintained extract, so coverage is partial and uneven by wilaya, denser in the north.\n\n**Source :** [GeoAlgeria](https://geoalgeria.com) par Yasser''s studio, paquet [@geoalgeria/pharmacies](https://www.npmjs.com/package/@geoalgeria/pharmacies).\n**Licence :** ODbL-1.0\n\nSynchronisé automatiquement chaque semaine par data-dz.", "categorie_slug": "sante", "licence_code": "ODbL-1.0", "licence_details": "ODbL-1.0", "url_source": "https://www.npmjs.com/package/@geoalgeria/pharmacies", "mots_cles": ["algeria", "health", "officine", "openstreetmap", "osm", "pharmacie", "pharmacies", "pharmacy", "صيدلية"], "wilayas": [], "frequence_maj": "hebdomadaire", "infos_source": {"bbox": [-8.139568, 21.328501, 9.574456, 37.065122], "paquet": "@geoalgeria/pharmacies", "couverture_pct": 34.6, "taux_geocodage": 100, "note_couverture": "3807 pharmacies compiled from OpenStreetMap, against an estimated ~11000 officines nationally (order-of-magnitude, no open official registry). A community-maintained extract, so coverage is partial and uneven by wilaya, denser in the north.", "nb_enregistrements": 3807, "nb_wilayas_couvertes": 67, "mis_a_jour_par_la_source": "2026-08-31"}}]'::jsonb) as x(
  slug text, titre jsonb, description jsonb, readme text, categorie_slug text, licence_code text, licence_details text,
  url_source text, mots_cles text[], wilayas text[], frequence_maj text, infos_source jsonb);

